ALTER procedure [api].[DeleteAssetType] @executionUid uniqueidentifier, @itemNumber int, @resource int as begin set nocount on;
declare @date datetime = getutcdate(), @success bit;
BEGIN TRANSACTION [Tran1]
BEGIN TRY
select @success = Success from api.ExecutionDeletedAssetType where ExecutionID = @executionUid and ItemNumber = @itemNumber and FromHierarchy = 0;
if @success is null or @success = 1 begin
with h as ( select D.ExecutionID, D.ItemNumber, D.AssetTypeID, D.[Uid], A.Object, A.ObjectID, D.IntersectTypeID, 0 as [Level] from api.ExecutionDeletedAssetType D inner join AssetType A on D.ExecutionID = @executionUid and A.ID = D.AssetTypeID and D.ItemNumber = @itemNumber where D.AssetTypeID is not null union all select P.ExecutionID, P.ItemNumber, C.ID as AssetTypeID, C.[Uid], C.Object, C.ObjectID, I.ID as IntersectTypeID, P.[Level] + 1 as [Level] from IntersectType I inner join h as P on P.ExecutionID = @executionUid and P.Object = I.Subject and P.ObjectID = I.SubjectID inner join AssetType C on C.Object = I.Object and C.ObjectID = I.ObjectID and C.ID <> P.AssetTypeID inner join [Predicate] PR on PR.ID = I.PredicateID and PR.[Type] in (3,4) where P.[Level] <= 15 ) insert into api.ExecutionDeletedAssetType ([ExecutionID],[ItemNumber],[Uid],[AssetTypeID],Object,ObjectID,[IntersectTypeID],[FromHierarchy]) select distinct ExecutionID, ItemNumber, [Uid], AssetTypeID, Object, ObjectID, IntersectTypeID, 1 from h where IntersectTypeID is not null and [Level] > 0 and Uid not in (select Uid from api.ExecutionDeletedAsset where ExecutionID = @executionUid);
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID],[AssetID]) select 'ObjectIndex', 'D', A.Object, A.ObjectID, A.ID from Asset A inner join api.ExecutionDeletedAssetType S on S.AssetTypeID = A.AssetTypeID and S.ExecutionID = @executionUid and S.ItemNumber = @itemNumber;
delete T from api.EntityFieldTypeMultiSelectField T inner join api.EntityFieldType F on F.ID = T.EntityFieldTypeID inner join api.Entity E on E.ID = F.EntityID inner join api.ExecutionDeletedAssetType S on S.AssetTypeID = E.AssetTypeID and S.ExecutionID = @executionUid and S.ItemNumber = @itemNumber;
delete T from api.EntityFieldType T inner join api.Entity E on E.ID = T.EntityID inner join api.ExecutionDeletedAssetType S on S.AssetTypeID = E.AssetTypeID and S.ExecutionID = @executionUid and S.ItemNumber = @itemNumber;
delete T from api.EntityUri T inner join api.Entity E on E.ID = T.EntityID inner join api.ExecutionDeletedAssetType S on S.AssetTypeID = E.AssetTypeID and S.ExecutionID = @executionUid and S.ItemNumber = @itemNumber;
delete T from api.Entity T inner join api.ExecutionDeletedAssetType S on S.AssetTypeID = T.AssetTypeID and S.ExecutionID = @executionUid and S.ItemNumber = @itemNumber;
delete T from Field T inner join [Attribute] A on T.ObjectType = 'Attribute' and A.ID = T.ObjectID inner join Asset O on O.Object = A.ObjectType and O.ObjectID = A.ObjectID inner join api.ExecutionDeletedAssetType S on S.AssetTypeID = O.AssetTypeID and S.ExecutionID = @executionUid and S.ItemNumber = @itemNumber;
delete T from [Attribute] T inner join Asset O on O.Object = T.ObjectType and O.ObjectID = T.ObjectID inner join api.ExecutionDeletedAssetType S on S.AssetTypeID = O.AssetTypeID and S.ExecutionID = @executionUid and S.ItemNumber = @itemNumber;
delete E from AttributeTypeRelation E inner join api.ExecutionDeletedAssetType S on S.Object = E.ObjectType and S.ObjectID = E.ObjectID and S.ExecutionID = @executionUid and S.ItemNumber = @itemNumber;
drop table if exists #w; create table #w (ID int);
insert into #w select distinct wi.ID from workflow.[Type] wt inner join workflow.EventRegistration we on we.typeid = wt.id and we.changetype <> 3 inner join workflow.[Version] wv on wt.id = wv.typeId inner join workflow.Item wi on wv.id = wi.VersionID inner join Asset A on A.Object = wi.Object and A.ObjectID = wi.ObjectID inner join api.ExecutionDeletedAssetType S on S.AssetTypeID = A.AssetTypeID and S.ExecutionID = @executionUid and S.ItemNumber = @itemNumber;
insert into #w select wi.id from workflow.Item wi inner join Issue i on wi.object = 'Issue' and i.id = wi.objectid inner join Asset A on A.Object = i.ObjectType and A.ObjectID = i.ObjectID inner join api.ExecutionDeletedAssetType S on S.AssetTypeID = A.AssetTypeID and S.ExecutionID = @executionUid and S.ItemNumber = @itemNumber;
delete T from [workflow].[ItemStepTransition] T inner join workflow.itemstep wis on (wis.ID = T.ToItemStepID or wis.ID = T.FromItemStepID) inner join #w S on S.ID = wis.ItemID;
delete workflow.itemstep where ItemID in (Select ID from #w);
delete T from [workflow].[ItemAssignment] T inner join #w S on S.ID = T.ItemID;
delete [workflow].[Item] where ID in (Select ID from #w);
truncate table #w;
insert into #w select distinct wt.ID from workflow.[Type] wt inner join workflow.EventRegistration we on we.typeid = wt.id and we.changetype <> 3 inner join api.ExecutionDeletedAssetType S on S.Object = we.Object and S.ObjectID = we.ObjectID and S.ExecutionID = @executionUid and S.ItemNumber = @itemNumber;
delete T from [workflow].[VersionStepTransition] T inner join workflow.Versionstep wis on (wis.ID = T.ToVersionStepID or wis.ID = T.FromVersionStepID) inner join [workflow].[Version] v on v.ID = wis.VersionID inner join [workflow].[Type] wt on wt.ID = v.TypeID inner join #w S on S.ID = wt.ID;
delete wis from workflow.Versionstep wis inner join [workflow].[Version] v on v.ID = wis.VersionID inner join [workflow].[Type] wt on wt.ID = v.TypeID inner join #w S on S.ID = wt.ID;
update wt set PublishedVersionID = null from workflow.type wt inner join #w S on S.ID = wt.ID;
delete v from [workflow].[Version] v inner join [workflow].[Type] wt on wt.ID = v.TypeID inner join #w S on S.ID = wt.ID;
delete wt from [workflow].[Type] wt inner join #w S on S.ID = wt.ID;
delete T from ResponsibilityRuleResultAsset T inner join ResponsibilityTypeRelationRule R on R.ID = T.RuleID inner join api.ExecutionDeletedAssetType S on S.Object = R.Object and S.ObjectID = R.ObjectID and S.ExecutionID = @executionUid and S.ItemNumber = @itemNumber;
