delete T from AssetCrossReference T inner join Asset A on A.Uid = T.Uid inner join api.ExecutionDeletedAssetType S on S.AssetTypeID = A.AssetTypeID and S.ExecutionID = @executionUid and S.ItemNumber = @itemNumber;
