delete T from [Intersect] T inner join Asset A on A.Object = T.Subject and A.ObjectID = T.SubjectID inner join api.ExecutionDeletedAssetType S on S.AssetTypeID = A.AssetTypeID and S.ExecutionID = @executionUid and S.ItemNumber = @itemNumber;
