update api.ExecutionDeletedAssetType set [Message] = 'Removed Asset type from environment, along with all related assets, scores, and relationships.', Success = 1 where ExecutionID = @executionUid and ItemNumber = @itemNumber and FromHierarchy = 0; end;
COMMIT TRANSACTION [Tran1]; END TRY BEGIN CATCH
ROLLBACK TRANSACTION [Tran1]
update api.ExecutionDeletedAssetType set [Message] = 'Error occurred: ' + ERROR_MESSAGE(), Success = 0 where ExecutionID = @executionUid and ItemNumber = @itemNumber and FromHierarchy = 0; END CATCH
