changeSet.sql:
ALTER FUNCTION [dbo].[GetAssetDisplayValueById] ( @Id bigint ) RETURNS TABLE AS RETURN (
select top 1 string_agg(coalesce(D.FormattedValue, D.value), '') as DisplayValue from dbo.Asset A inner join dbo.AssetType T on T.ID = A.AssetTypeID outer apply ( select TF.value, coalesce(case when TF.Value = 'FirstName' then R.FirstName + ' ' else R.LastName end, F.FormattedValue, A.Code, FA.Name, GRP.Name) as FormattedValue from string_split(replace(replace(T.DisplayFormat, '{', '|'),'}','|'), '|') TF left join dbo.FieldType FT on FT.AssetTypeID = T.ID and FT.Name = TF.Value left join dbo.Field F on F.FieldTypeID = FT.ID and F.AssetID = A.ID left join dbo.FusionAttribute FA on TF.Value = 'Name' and A.Object = 'FusionAttribute' and FA.ID = A.ObjectID left join reporting.Global_resource R on TF.Value in ('FirstName', 'LastName') and A.Object = 'Resource' and R.ResourceID = A.ObjectID left join dbo.[Group] GRP on A.Object = 'Group' and GRP.ID = A.ObjectID where RTRIM(TF.value) <> '' ) D where A.ID = @Id
)

changeSet.rollback:
ALTER FUNCTION [dbo].[GetAssetDisplayValueById] ( @Id bigint ) RETURNS TABLE AS RETURN (
select top 1 string_agg(coalesce(D.FormattedValue, D.value), '') as DisplayValue from dbo.Asset A inner join dbo.AssetType T on T.ID = A.AssetTypeID outer apply ( select TF.value, coalesce(case when TF.Value = 'FirstName' then R.FirstName + ' ' else R.LastName end, F.FormattedValue, RI.Code, FA.Name, GRP.Name) as FormattedValue from string_split(replace(replace(T.DisplayFormat, '{', '|'),'}','|'), '|') TF left join dbo.FieldType FT on FT.AssetTypeID = T.ID and FT.Name = TF.Value left join dbo.Field F on F.FieldTypeID = FT.ID and F.AssetID = A.ID left join dbo.ReferenceItem RI on TF.Value = 'Code' and A.Object = 'ReferenceItem' and RI.ID = A.ObjectID left join dbo.FusionAttribute FA on TF.Value = 'Name' and A.Object = 'FusionAttribute' and FA.ID = A.ObjectID left join reporting.Global_resource R on TF.Value in ('FirstName', 'LastName') and A.Object = 'Resource' and R.ResourceID = A.ObjectID left join dbo.[Group] GRP on A.Object = 'Group' and GRP.ID = A.ObjectID where RTRIM(TF.value) <> '' ) D where A.ID = @Id
)

changeSet.sql:
ALTER FUNCTION [dbo].[GetAssetKeyHashById]( @Id bigint ) RETURNS TABLE AS RETURN (
select A.AssetTypeID, A.ID, CONVERT( varchar(32), SUBSTRING(HASHBYTES('SHA1', STRING_AGG(cast(FieldTypeID as nvarchar) + ':' + Value, char(59))), 3, 32), 2) as KeyHash from Asset A inner join Field F on F.ObjectType = A.Object and F.ObjectID = A.ObjectID inner join FieldType FT on FT.ID = F.FieldTypeID and FT.AssetTypeID = A.AssetTypeID and FT.IsPartOfKey = 1 where a.id = @id group by A.AssetTypeID, A.ID
)

changeSet.rollback:
ALTER FUNCTION [dbo].[GetAssetKeyHashById]( @Id bigint ) RETURNS TABLE AS RETURN (
select A.AssetTypeID, A.ID, CONVERT( varchar(32), SUBSTRING(HASHBYTES('SHA1', STRING_AGG(cast(FieldTypeID as nvarchar) + ':' + Value, char(59))), 3, 32), 2) as KeyHash from Asset A inner join Field F on F.ObjectType = A.Object and F.ObjectID = A.ObjectID and A.Object != 'ReferenceItem' inner join FieldType FT on FT.ID = F.FieldTypeID and FT.AssetTypeID = A.AssetTypeID and FT.IsPartOfKey = 1 where a.id = @id group by A.AssetTypeID, A.ID union select A.AssetTypeID, A.ID, CONVERT( varchar(32), SUBSTRING(HASHBYTES('SHA1', STRING_AGG(r.code, char(59))), 3, 32), 2) as KeyHash from Asset A inner join referenceitem r on (a.object = 'ReferenceItem' and r.id = a.objectid) where a.id = @id group by A.AssetTypeID, A.ID
)

